-- Shared operational issues and explicit cue blockers. No alerts/messages are sent.
begin;
create table if not exists public.cb_experience_issues(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.cb_project_events on delete cascade,item_id uuid references public.cb_experience_items,data jsonb not null,assignee uuid references auth.users,blocks boolean not null default false,revision bigint not null default 1,created_by uuid not null references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.cb_experience_issue_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_issue_history(issue_id uuid not null references public.cb_experience_issues on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(issue_id,revision));
alter table public.cb_experience_issues enable row level security;alter table public.cb_experience_issue_writes enable row level security;alter table public.cb_experience_issue_history enable row level security;
revoke all on public.cb_experience_issues,public.cb_experience_issue_writes,public.cb_experience_issue_history from public,anon,authenticated;
create index if not exists cb_experience_issue_event on public.cb_experience_issues(event_id);
create or replace function public.cb_experience_issue_board(p_event uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare e public.cb_project_events;can_write boolean;begin
 select * into e from public.cb_project_events where id=p_event;if e.id is null or not coalesce(public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration access required' using errcode='42501';end if;can_write=public.cb_project_access(e.project_id,'write');
 return jsonb_build_object('event',e.id,'event_revision',e.revision,'can_edit',can_write,'title',e.title,'items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'title',i.data->>'title','revision',i.revision) order by i.data->>'title',i.id),'[]') from public.cb_experience_items i where i.event_id=e.id),'people',case when can_write then (select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',coalesce(p.full_name,'Wedding collaborator')) order by p.full_name,x.id),'[]') from (select owner_id id from public.cb_projects where id=e.project_id union select user_id from public.cb_members where project_id=e.project_id) x left join public.cb_profiles p on p.user_id=x.id where public.cb_experience_member(e.id,x.id)) else '[]'::jsonb end,'issues',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'item',i.item_id,'data',i.data,'assignee',i.assignee,'assignee_name',case when public.cb_experience_member(e.id,i.assignee) then (select full_name from public.cb_profiles where user_id=i.assignee) else null end,'blocks',i.blocks,'revision',i.revision,'created_at',i.created_at,'updated_at',i.updated_at,'resolved_at',i.resolved_at,'history',case when can_write then (select coalesce(jsonb_agg(jsonb_build_object('revision',h.revision,'at',h.at,'status',h.snapshot->'data'->>'status','blocks',h.snapshot->'blocks') order by h.revision desc),'[]') from (select * from public.cb_experience_issue_history where issue_id=i.id order by revision desc limit 20) h) else '[]'::jsonb end) order by (i.data->>'status'='Resolved'),(case i.data->>'severity' when 'High' then 0 when 'Medium' then 1 else 2 end),i.created_at,i.id),'[]') from public.cb_experience_issues i where i.event_id=e.id));end;$$;
create or replace function public.cb_save_experience_issue(p_event uuid,p_event_revision bigint,p_id uuid,p_revision bigint,p_client uuid,p_item uuid,p_item_revision bigint,p_data jsonb,p_assignee uuid,p_blocks boolean,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare e public.cb_project_events;i public.cb_experience_issues;src public.cb_experience_items;w public.cb_experience_issue_writes;payload jsonb;result jsonb;k text;begin
 select * into e from public.cb_project_events where id=p_event;perform 1 from public.cb_projects where id=e.project_id for update;select * into e from public.cb_project_events where id=p_event for update;
 if e.id is null or not coalesce(public.cb_project_access(e.project_id,'write') and public.cb_experience_member(e.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 payload=jsonb_build_object('event',p_event,'event_revision',p_event_revision,'id',p_id,'revision',p_revision,'item',p_item,'item_revision',p_item_revision,'data',p_data,'assignee',p_assignee,'blocks',p_blocks,'confirm',p_confirm);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_issue_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original issue report' using errcode='PT409';end if;return w.response;end if;
 if p_confirm is distinct from true or p_blocks is null then raise exception 'Review and confirm the shared issue and cue impact';end if;
 if e.revision is distinct from p_event_revision then raise exception 'The celebration changed. Refresh before saving the issue.' using errcode='PT409';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or p_data-array['title','details','severity','status','resolution']::text[]<>'{}' then raise exception 'Review issue fields';end if;
 foreach k in array array['title','details','severity','status','resolution'] loop if jsonb_typeof(p_data->k) is distinct from 'string' or length(p_data->>k)>(case k when 'details' then 3000 when 'resolution' then 2000 else 200 end) then raise exception 'Review issue text limits';end if;end loop;
 if length(btrim(p_data->>'title'))=0 or p_data->>'severity' not in ('Low','Medium','High') or p_data->>'status' not in ('Open','Investigating','Resolved') then raise exception 'Choose a title, severity and issue status';end if;
 if p_data->>'status'='Resolved' and length(btrim(p_data->>'resolution'))=0 then raise exception 'Record how the issue was resolved';end if;
 if p_item is not null then select * into src from public.cb_experience_items where id=p_item and event_id=e.id for update;if src.id is null then raise exception 'Choose a service in this celebration' using errcode='42501';end if;if src.revision is distinct from p_item_revision then raise exception 'The affected service changed. Refresh before saving.' using errcode='PT409';end if;elsif p_item_revision is not null then raise exception 'Clear the service revision for a celebration-wide issue';end if;
 if p_assignee is not null and not public.cb_experience_member(e.id,p_assignee) then raise exception 'Choose an accepted collaborator with celebration access';end if;
 if p_id is null then if p_revision is distinct from 0::bigint then raise exception 'Refresh before reporting a new issue' using errcode='PT409';end if;if (select count(*) from public.cb_experience_issues where event_id=e.id)>=1000 then raise exception 'Celebration issue allowance reached';end if;insert into public.cb_experience_issues(event_id,item_id,data,assignee,blocks,created_by,resolved_at) values(e.id,p_item,p_data,p_assignee,p_blocks,auth.uid(),case when p_data->>'status'='Resolved' then now() end) returning * into i;
 else select * into i from public.cb_experience_issues where id=p_id and event_id=e.id for update;if i.id is null then raise exception 'Choose an issue in this celebration' using errcode='42501';end if;if i.revision is distinct from p_revision then raise exception 'Another coordinator updated this issue. Refresh first.' using errcode='PT409';end if;
 update public.cb_experience_issues set item_id=p_item,data=p_data,assignee=p_assignee,blocks=p_blocks,revision=revision+1,updated_at=now(),resolved_at=case when p_data->>'status'<>'Resolved' then null when i.data->>'status'='Resolved' then i.resolved_at else now() end where id=i.id returning * into i;end if;
 insert into public.cb_experience_issue_history values(i.id,i.revision,auth.uid(),to_jsonb(i),now());result=jsonb_build_object('saved',true,'id',i.id,'revision',i.revision);insert into public.cb_experience_issue_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
create or replace function public.cb_experience_cue_blocker() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.status='Running' and (tg_op='INSERT' or old.status is distinct from 'Running') and exists(select 1 from public.cb_experience_issues i where i.event_id=new.event_id and i.blocks and i.data->>'status'<>'Resolved' and (i.item_id is null or i.item_id=new.item_id)) then raise exception 'Resolve or clear the blocking issue under Issues before starting this cue.';end if;return new;
end;$$;
drop trigger if exists cb_experience_cue_blocker on public.cb_experience_cues;
create trigger cb_experience_cue_blocker before insert or update of status on public.cb_experience_cues for each row execute function public.cb_experience_cue_blocker();
revoke all on function public.cb_experience_issue_board(uuid),public.cb_save_experience_issue(uuid,bigint,uuid,bigint,uuid,uuid,bigint,jsonb,uuid,boolean,boolean),public.cb_experience_cue_blocker() from public,anon,authenticated;
grant execute on function public.cb_experience_issue_board(uuid),public.cb_save_experience_issue(uuid,bigint,uuid,bigint,uuid,uuid,bigint,jsonb,uuid,boolean,boolean) to authenticated;
notify pgrst,'reload schema';commit;
